package com.raavana.thirdparty.utils;

public class PdfCompressionException extends Exception {
    public PdfCompressionException() {
        super();
    }
    public PdfCompressionException(String message) {
        super(message);
    }
    public PdfCompressionException(String message, Throwable cause) {
        super(message, cause);
    }
    public PdfCompressionException(Throwable cause) {
        super(cause);
    }
}


